  // The uploaded archive (if any) is no longer needed once the import has
  // completed, clear the scratch data and remove the archive.
  const storageKey = importModel.scratch?.storageKey;
  const archive = storageKey
    ? await Attachment.findOne({
        where: { teamId: importModel.teamId, key: storageKey },
        transaction,
      })
    : null;

  importModel.state = ImportState.Completed;
  importModel.error = null; // unset any error from previous attempts.
  importModel.scratch = null;
  await importModel.saveWithCtx(
    createContext({
      user: importModel.createdBy,
      transaction,
    })
  );

  if (archive) {
    // Delete after commit so the file is only removed from storage once
    // the import is persisted as completed.
    transaction.afterCommit(async () => {
      try {
        await archive.destroy();
      } catch (err) {
        Logger.error("Failed to delete import archive", err, {
          importId: importModel.id,
          attachmentId: archive.id,
        });
      }
    });
